/** Owned per-case validation service. No reset endpoint or shared business state. */
import {spawn} from 'node:child_process';import {createRequire} from 'node:module';import {businessCommandEnvironment} from './aidlc-spawn';
const R=createRequire(import.meta.url)('./aidlc-owned-resource.cjs');
export async function startCaseService(root:string,plan:any,owner:string,deadline:number){
 if(!Number.isFinite(deadline)||deadline<=Date.now())throw Error('CASE_SERVICE_DEADLINE');const start=performance.now(),child=spawn(plan.argv[0],plan.argv.slice(1),{cwd:root,env:{...businessCommandEnvironment(process.env),PILOT_PORT:'0'},stdio:['ignore','pipe','pipe'],windowsHide:true,detached:process.platform!=='win32'}),resource=R.ownChild(child,{kind:'service',owner,tree:true,deadline_at:deadline,requestClose:()=>resource.signal('SIGTERM')});let ready=false,stderr='';child.stderr.on('data',b=>{stderr=(stderr+b).slice(-4000);});
 try{const info=await R.bounded(new Promise<any>((resolve,reject)=>{let text='';child.stdout.on('data',b=>{if(ready)return;text+=String(b);if(text.length>4096)return reject(Error('CASE_SERVICE_OUTPUT_LIMIT'));if(!text.includes('\n'))return;try{resolve(JSON.parse(text.split('\n')[0]));}catch(e){reject(e);}finally{ready=true;text='';}});child.once('error',reject);child.once('close',()=>reject(Error('CASE_SERVICE_EXIT_BEFORE_READY')));}),R.deadlineAfter(Math.max(0,Math.min(plan.timeout_ms,deadline-Date.now()))),'CASE_SERVICE_START_TIMEOUT');const port=typeof info==='number'?info:info?.port;if(!Number.isInteger(port)||port<1||port>65535)throw Error('CASE_SERVICE_PORT_INVALID');return {origin:'http://127.0.0.1:'+port,resource,startup_ms:performance.now()-start,close:()=>resource.close()};}
 catch(error){const closed=await resource.close();if(!closed.reconciled)throw R.resourceError(closed,error);throw Object.assign(Error('CASE_SERVICE_START_FAILED: '+stderr),{cause:error});}finally{ready=true;}
}
